package multipartbody

import (
	"bytes"
	"fmt"
	"io"
	"mime/multipart"
)

// TextField is a plain-text form field written alongside the file part in a
// multipart/form-data body.
type TextField struct {
	Name  string
	Value string
}

// NewFile encodes src as a multipart/form-data body with a single file part.
//
// It returns the Content-Type header value and a *bytes.Reader over the
// encoded body. Because *bytes.Reader is recognized by http.NewRequest,
// the resulting request automatically gets a working GetBody, which
// makes retries (e.g. on 429 / 5xx) safe without any extra wiring.
func NewFile(fieldName, fileName string, src io.Reader) (string, *bytes.Reader, error) {
	return NewFileWithFields(fieldName, fileName, src, nil)
}

// NewFileWithFields is like NewFile but also writes zero or more plain-text
// form fields before the file part. Like NewFile it returns a *bytes.Reader, so
// the resulting request gets a working GetBody and stays retry-safe.
func NewFileWithFields(fieldName, fileName string, src io.Reader, fields []TextField) (string, *bytes.Reader, error) {
	if fieldName == "" {
		return "", nil, fmt.Errorf("multipart field name is required")
	}
	if fileName == "" {
		return "", nil, fmt.Errorf("multipart file name is required")
	}
	if src == nil {
		return "", nil, fmt.Errorf("multipart file content is required")
	}

	var buf bytes.Buffer
	writer := multipart.NewWriter(&buf)

	for _, field := range fields {
		if field.Name == "" {
			return "", nil, fmt.Errorf("multipart field name is required")
		}
		if err := writer.WriteField(field.Name, field.Value); err != nil {
			return "", nil, fmt.Errorf("write multipart field %q: %w", field.Name, err)
		}
	}

	part, err := writer.CreateFormFile(fieldName, fileName)
	if err != nil {
		return "", nil, fmt.Errorf("create multipart file: %w", err)
	}
	if _, err := io.Copy(part, src); err != nil {
		return "", nil, fmt.Errorf("write multipart file: %w", err)
	}
	if err := writer.Close(); err != nil {
		return "", nil, fmt.Errorf("close multipart writer: %w", err)
	}

	return writer.FormDataContentType(), bytes.NewReader(buf.Bytes()), nil
}

package v1

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"sort"
	"strconv"
	"strings"

	"github.com/juhokoskela/pipedrive-go/internal/multipartbody"
	"github.com/juhokoskela/pipedrive-go/pipedrive"
)

type File struct {
	ID          FileID          `json:"id,omitempty"`
	Name        string          `json:"name,omitempty"`
	FileName    string          `json:"file_name,omitempty"`
	FileType    string          `json:"file_type,omitempty"`
	FileSize    int             `json:"file_size,omitempty"`
	Description string          `json:"description,omitempty"`
	URL         string          `json:"url,omitempty"`
	UserID      *UserID         `json:"user_id,omitempty"`
	DealID      *DealID         `json:"deal_id,omitempty"`
	PersonID    *PersonID       `json:"person_id,omitempty"`
	OrgID       *OrganizationID `json:"org_id,omitempty"`
	ProductID   *ProductID      `json:"product_id,omitempty"`
	ActivityID  *ActivityID     `json:"activity_id,omitempty"`
	LeadID      *LeadID         `json:"lead_id,omitempty"`
	Active      bool            `json:"active_flag,omitempty"`
	Inline      bool            `json:"inline_flag,omitempty"`
	AddTime     *DateTime       `json:"add_time,omitempty"`
	UpdateTime  *DateTime       `json:"update_time,omitempty"`
}

type FilesService struct {
	client *Client
}

type FilesOption interface {
	applyFiles(*filesOptions)
}

type filesOptions struct {
	query          url.Values
	form           url.Values
	requestOptions []pipedrive.RequestOption
}

type filesOptionFunc func(*filesOptions)

func (f filesOptionFunc) applyFiles(cfg *filesOptions) {
	f(cfg)
}

func (cfg *filesOptions) setForm(key, value string) {
	if cfg.form == nil {
		cfg.form = url.Values{}
	}
	cfg.form.Set(key, value)
}

func WithFilesQuery(values url.Values) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.query = mergeQueryValues(cfg.query, values)
	})
}

// The following options attach an uploaded file to a Pipedrive record. They
// apply to AddFile, which sends them as multipart form fields; other Files
// methods ignore them.

func WithFileDealID(id DealID) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.setForm("deal_id", strconv.FormatInt(int64(id), 10))
	})
}

func WithFilePersonID(id PersonID) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.setForm("person_id", strconv.FormatInt(int64(id), 10))
	})
}

func WithFileOrganizationID(id OrganizationID) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.setForm("org_id", strconv.FormatInt(int64(id), 10))
	})
}

func WithFileProductID(id ProductID) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.setForm("product_id", strconv.FormatInt(int64(id), 10))
	})
}

func WithFileActivityID(id ActivityID) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.setForm("activity_id", strconv.FormatInt(int64(id), 10))
	})
}

func WithFileLeadID(id LeadID) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.setForm("lead_id", string(id))
	})
}

func WithFilesRequestOptions(opts ...pipedrive.RequestOption) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.requestOptions = append(cfg.requestOptions, opts...)
	})
}

func newFilesOptions(opts []FilesOption) filesOptions {
	var cfg filesOptions
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		opt.applyFiles(&cfg)
	}
	return cfg
}

func (s *FilesService) List(ctx context.Context, opts ...FilesOption) ([]File, *Pagination, error) {
	cfg := newFilesOptions(opts)

	var payload struct {
		Data           []File `json:"data"`
		AdditionalData *struct {
			Pagination *Pagination `json:"pagination"`
		} `json:"additional_data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodGet, "/files", cfg.query, nil, &payload, cfg.requestOptions...); err != nil {
		return nil, nil, err
	}
	var page *Pagination
	if payload.AdditionalData != nil {
		page = payload.AdditionalData.Pagination
	}
	return payload.Data, page, nil
}

func (s *FilesService) Get(ctx context.Context, id FileID, opts ...FilesOption) (*File, error) {
	if err := validateID(id, "file id"); err != nil {
		return nil, err
	}
	cfg := newFilesOptions(opts)
	path := fmt.Sprintf("/files/%d", id)

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodGet, path, cfg.query, nil, &payload, cfg.requestOptions...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}

// Add uploads a file from a pre-built request body and Content-Type. It is the
// low-level escape hatch for callers that need full control over the
// multipart/form-data payload; most callers should prefer AddFile, which builds
// the body for you.
//
// The supplied body is retried on 429/5xx only when it can be replayed, i.e.
// when its concrete type is one net/http can rewind (*bytes.Reader,
// *bytes.Buffer, *strings.Reader). An arbitrary stream such as an *os.File has
// no replayable body, so such a request fails on the first 429 instead of
// retrying. Use AddFile (which buffers into a *bytes.Reader) when you want
// uploads to participate in the retry policy.
func (s *FilesService) Add(ctx context.Context, body io.Reader, contentType string, opts ...FilesOption) (*File, error) {
	cfg := newFilesOptions(opts)
	if body == nil {
		return nil, fmt.Errorf("file body is required")
	}
	if contentType == "" {
		return nil, fmt.Errorf("content type is required")
	}

	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}

// AddFile uploads a local file, building the multipart/form-data body for you.
// Pass a file name and a reader over the file's contents — for example a
// *os.File returned by os.Open — instead of assembling the body and
// Content-Type by hand as Add requires.
//
// The contents are buffered into a *bytes.Reader, so the request carries a
// GetBody and is safely retried on 429/5xx under the configured retry policy.
// Associate the file with a record using the WithFile*ID options.
func (s *FilesService) AddFile(ctx context.Context, fileName string, content io.Reader, opts ...FilesOption) (*File, error) {
	cfg := newFilesOptions(opts)
	if fileName == "" {
		return nil, fmt.Errorf("file name is required")
	}
	if content == nil {
		return nil, fmt.Errorf("file content is required")
	}

	var fields []multipartbody.TextField
	if len(cfg.form) > 0 {
		keys := make([]string, 0, len(cfg.form))
		for k := range cfg.form {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			fields = append(fields, multipartbody.TextField{Name: k, Value: cfg.form.Get(k)})
		}
	}

	contentType, body, err := multipartbody.NewFileWithFields("file", fileName, content, fields)
	if err != nil {
		return nil, err
	}

	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}

func (s *FilesService) AddRemoteFile(ctx context.Context, form url.Values, opts ...FilesOption) (*File, error) {
	cfg := newFilesOptions(opts)
	if len(form) == 0 {
		return nil, fmt.Errorf("form values are required")
	}

	body := strings.NewReader(form.Encode())
	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", "application/x-www-form-urlencoded"))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files/remote", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing remote file data in response")
	}
	return payload.Data, nil
}

func (s *FilesService) LinkRemoteFile(ctx context.Context, form url.Values, opts ...FilesOption) (*File, error) {
	cfg := newFilesOptions(opts)
	if len(form) == 0 {
		return nil, fmt.Errorf("form values are required")
	}

	body := strings.NewReader(form.Encode())
	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", "application/x-www-form-urlencoded"))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files/remoteLink", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing linked file data in response")
	}
	return payload.Data, nil
}

func (s *FilesService) Update(ctx context.Context, id FileID, body io.Reader, contentType string, opts ...FilesOption) (*File, error) {
	if err := validateID(id, "file id"); err != nil {
		return nil, err
	}
	cfg := newFilesOptions(opts)
	if body == nil {
		return nil, fmt.Errorf("file body is required")
	}
	if contentType == "" {
		return nil, fmt.Errorf("content type is required")
	}

	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	path := fmt.Sprintf("/files/%d", id)
	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPut, path, cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file update data in response")
	}
	return payload.Data, nil
}

func (s *FilesService) Delete(ctx context.Context, id FileID, opts ...FilesOption) (bool, error) {
	if err := validateID(id, "file id"); err != nil {
		return false, err
	}
	cfg := newFilesOptions(opts)
	path := fmt.Sprintf("/files/%d", id)

	var payload struct {
		Success *bool `json:"success"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodDelete, path, cfg.query, nil, &payload, cfg.requestOptions...); err != nil {
		return false, err
	}
	if payload.Success == nil {
		return false, fmt.Errorf("missing file delete success in response")
	}
	return *payload.Success, nil
}

func (s *FilesService) Download(ctx context.Context, id FileID, opts ...FilesOption) ([]byte, error) {
	if err := validateID(id, "file id"); err != nil {
		return nil, err
	}
	cfg := newFilesOptions(opts)
	ctx, editors := pipedrive.ApplyRequestOptions(ctx, cfg.requestOptions...)

	resp, err := s.client.gen.DownloadFile(ctx, int(id), toRequestEditors(editors)...)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("read response: %w", err)
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return nil, errorFromResponse(resp, body)
	}
	return body, nil
}

func (s *FilesService) DownloadTo(ctx context.Context, id FileID, dst io.Writer, opts ...FilesOption) error {
	if err := validateID(id, "file id"); err != nil {
		return err
	}
	if dst == nil {
		return fmt.Errorf("download destination is required")
	}

	cfg := newFilesOptions(opts)
	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithNoResponseSizeLimit())
	ctx, editors := pipedrive.ApplyRequestOptions(ctx, reqOpts...)

	resp, err := s.client.gen.DownloadFile(ctx, int(id), toRequestEditors(editors)...)
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
		if err != nil {
			return fmt.Errorf("read response: %w", err)
		}
		return errorFromResponse(resp, body)
	}
	if _, err := io.Copy(dst, resp.Body); err != nil {
		return fmt.Errorf("write download: %w", err)
	}
	return nil
}

